class Solution {
    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        java.util.Set<Integer> blocked = new java.util.HashSet<>();
        int farthest = x;
        for (int value : forbidden) {
            blocked.add(value);
            farthest = Math.max(farthest, value);
        }
        if (blocked.contains(x)) {
            return -1;
        }

        int limit = farthest + a + b + 2000;
        boolean[][] seen = new boolean[limit + 1][2];
        java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
        queue.offer(new int[]{0, 0, 0});
        seen[0][0] = true;

        while (!queue.isEmpty()) {
            int[] state = queue.poll();
            int position = state[0];
            int previousBack = state[1];
            int distance = state[2];
            if (position == x) {
                return distance;
            }

            int forward = position + a;
            if (forward <= limit && !blocked.contains(forward) && !seen[forward][0]) {
                seen[forward][0] = true;
                queue.offer(new int[]{forward, 0, distance + 1});
            }

            int backward = position - b;
            if (previousBack == 0 && backward >= 0 && !blocked.contains(backward) && !seen[backward][1]) {
                seen[backward][1] = true;
                queue.offer(new int[]{backward, 1, distance + 1});
            }
        }
        return -1;
    }
}

