class Solution {
    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        java.util.Set<Integer> blocked = new java.util.HashSet<>();
        int farthest = x;
        for (int value : forbidden) {
            blocked.add(value);
            farthest = Math.max(farthest, value);
        }
        if (blocked.contains(x)) {
            return -1;
        }

        int limit = farthest + a + b + 2000;
        boolean[][] seen = new boolean[limit + 1][2];
        java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
        queue.offer(new int[]{x, 0, 0});
        queue.offer(new int[]{x, 1, 0});
        seen[x][0] = true;
        seen[x][1] = true;

        while (!queue.isEmpty()) {
            int[] state = queue.poll();
            int position = state[0];
            int previousBack = state[1];
            int distance = state[2];
            if (position == 0 && previousBack == 0) {
                return distance;
            }

            if (previousBack == 0) {
                int previous = position - a;
                if (previous >= 0 && !blocked.contains(previous)) {
                    if (!seen[previous][0]) {
                        seen[previous][0] = true;
                        queue.offer(new int[]{previous, 0, distance + 1});
                    }
                    if (!seen[previous][1]) {
                        seen[previous][1] = true;
                        queue.offer(new int[]{previous, 1, distance + 1});
                    }
                }
            } else {
                int previous = position + b;
                if (previous <= limit && !blocked.contains(previous) && !seen[previous][0]) {
                    seen[previous][0] = true;
                    queue.offer(new int[]{previous, 0, distance + 1});
                }
            }
        }
        return -1;
    }
}

class Solution {
    private java.util.Set<Integer> blocked;
    private int a;
    private int b;
    private int limit;

    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        this.a = a;
        this.b = b;
        blocked = new java.util.HashSet<>();
        int farthest = x;
        for (int value : forbidden) {
            blocked.add(value);
            farthest = Math.max(farthest, value);
        }
        if (blocked.contains(x)) {
            return -1;
        }
        limit = farthest + a + b + 2000;

        java.util.Set<Integer> front = new java.util.HashSet<>();
        java.util.Set<Integer> back = new java.util.HashSet<>();
        java.util.Set<Integer> seenFront = new java.util.HashSet<>();
        java.util.Set<Integer> seenBack = new java.util.HashSet<>();
        front.add(encode(0, 0));
        seenFront.add(encode(0, 0));
        back.add(encode(x, 0));
        back.add(encode(x, 1));
        seenBack.add(encode(x, 0));
        seenBack.add(encode(x, 1));

        boolean fromStart = true;
        int jumps = 0;
        while (!front.isEmpty() && !back.isEmpty()) {
            if (front.size() > back.size()) {
                java.util.Set<Integer> temp = front;
                front = back;
                back = temp;
                temp = seenFront;
                seenFront = seenBack;
                seenBack = temp;
                fromStart = !fromStart;
            }

            java.util.Set<Integer> nextFront = new java.util.HashSet<>();
            for (int state : front) {
                if (back.contains(state)) {
                    return jumps;
                }
                for (int next : neighbors(state, fromStart)) {
                    if (seenBack.contains(next)) {
                        return jumps + 1;
                    }
                    if (seenFront.add(next)) {
                        nextFront.add(next);
                    }
                }
            }
            front = nextFront;
            jumps++;
        }
        return -1;
    }

    private java.util.List<Integer> neighbors(int state, boolean fromStart) {
        int position = state / 2;
        int previousBack = state % 2;
        java.util.List<Integer> next = new java.util.ArrayList<>();
        if (fromStart) {
            int forward = position + a;
            if (forward <= limit && !blocked.contains(forward)) {
                next.add(encode(forward, 0));
            }
            int backward = position - b;
            if (previousBack == 0 && backward >= 0 && !blocked.contains(backward)) {
                next.add(encode(backward, 1));
            }
        } else if (previousBack == 0) {
            int previous = position - a;
            if (previous >= 0 && !blocked.contains(previous)) {
                next.add(encode(previous, 0));
                next.add(encode(previous, 1));
            }
        } else {
            int previous = position + b;
            if (previous <= limit && !blocked.contains(previous)) {
                next.add(encode(previous, 0));
            }
        }
        return next;
    }

    private int encode(int position, int previousBack) {
        return position * 2 + previousBack;
    }
}
